Function.prototype.myBind = function (thisArg, ...partials) {
  const fn = this;
  return function (...args) {
    return fn.apply(thisArg, [...partials, ...args]);
  };
};

const obj = { x: 10, add(y) { return this.x + y; } };
const add5 = obj.add.myBind(obj, 5);
add5(3); // 18

function once(fn) {
  let called = false;
  let result;
  return function (...args) {
    if (!called) {
      called = true;
      result = fn.apply(this, args);
    }
    return result;
  };
}
const init = once(() => connectRedis());

function flatten(arr, depth = 1) {
  return depth > 0
    ? arr.reduce((acc, val) => acc.concat(
        Array.isArray(val) ? flatten(val, depth - 1) : val
      ), [])
    : arr.slice();
}
flatten([1, [2, [3]]], 2); // [1, 2, 3]

